-- mod-bots: names for bot characters, generated by modules/mod-bots/tools/bot_names.py; edit the
-- lists there and run it again rather than editing this file. Every name passes the server's name
-- rules and the client's reserved-name and profanity lists.

DROP TABLE IF EXISTS `bot_names`;
CREATE TABLE `bot_names` (
  `name` VARCHAR(12) NOT NULL,
  `gender` TINYINT UNSIGNED NOT NULL COMMENT '0 male, 1 female, 2 either',
  `style` TINYINT UNSIGNED NOT NULL COMMENT '0 plain fantasy, 1 funny, 2 gamer',
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

